  tools.exec_command({cmd:"rg -n 'tokenDeletedEnabled|token:deleted|Auth.*Grpc|auth.*[Gg][Rr][Pp][Cc]|audit.*[Cc]hecker|auditChecker' -g '!vendor' -g '!node_modules' -g '!**/.git/**' .",workdir:"/app",max_output_tokens:10000}),
  tools.exec_command({cmd:"rg --files | head -80",workdir:"/app",max_output_tokens:3000})
]); for (let i=0;i<r.length;i++) text(JSON.stringify({i,result:r[i]}));

const r=await Promise.allSettled([
tools.exec_command({cmd:"find . -name AGENTS.md -not -path './.git/*' -print",workdir:"/app",max_output_tokens:1000}),
