tools.exec_command({cmd:"grep -RIn --exclude-dir=.git --exclude-dir=node_modules --exclude-dir=vendor -E 'tokenDeletedEnabled|token:deleted|auditChecker|audit.*[Cc]hecker' . | head -200",workdir:"/app",max_output_tokens:8000})
]); for(let i=0;i<r.length;i++)text(JSON.stringify({i,result:r[i]}));

const r=await Promise.allSettled([
tools.exec_command({cmd:"sed -n '1,430p' internal/cmd/grpc.go",workdir:"/app",max_output_tokens:18000}),
tools.exec_command({cmd:"grep -RIn --exclude-dir=.git -E 'NewServer\\(|type Server struct|DeleteToken|RevokeToken|token.*deleted|TokenDeleted' internal/server internal | head -250",workdir:"/app",max_output_tokens:12000}),
