	}

	return req
}

// WithID is an option which predicates a delete with a specific authentication ID.
func WithID(id string) containers.Option[DeleteAuthenticationsRequest] {
	return func(r *DeleteAuthenticationsRequest) {
		r.ID = &id
	}
}

